#!/usr/bin/env python3
"""Validate English source catalogs and deterministically generate Rust metadata."""
import argparse
import json
from pathlib import Path
import re
import sys

KINDS = {"text": "Text", "code": "Code", "path": "Path",
         "number": "Number", "message": "Message"}
ID = re.compile(r"[a-z][a-z0-9_]*(?:\.[a-z][a-z0-9_]*)+")
NAME = re.compile(r"[A-Za-z0-9_]+")
HEADER = (
    "// @generated by tools/i18n/catalog.py; edit locales/en.json or locales/en/*.json.\n"
    "// Stable IDs/parameters are machine data; patterns are human presentation only.\n"
    "use super::{Definition, Parameter, ParameterKind};\n"
    "#[rustfmt::skip]\n"
    "pub(super) static MESSAGES: &[Definition] = &[\n"
)

def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON key: " + key)
        result[key] = value
    return result

def placeholders(pattern):
    names = set()
    offset = 0
    while offset < len(pattern):
        if pattern.startswith(("{{", "}}"), offset):
            offset += 2
        elif pattern[offset] == "{":
            end = pattern.find("}", offset + 1)
            if end < 0 or not NAME.fullmatch(pattern[offset + 1:end]):
                raise ValueError("invalid named placeholder")
            names.add(pattern[offset + 1:end])
            offset = end + 1
        elif pattern[offset] == "}":
            raise ValueError("unescaped closing brace")
        else:
            offset += 1
    return names

def source_text(value, label, nonempty=False):
    if not isinstance(value, str) or (nonempty and not value):
        raise ValueError(label + " must be text")
    # Invalid surrogate code points must not become invalid UTF-8/Rust source.
    value.encode("utf-8")
    return value

def validate_message(message_id, entry):
    if not ID.fullmatch(message_id):
        raise ValueError("invalid stable message ID: " + message_id)
    required = {"context", "parameters", "forms"}
    if not isinstance(entry, dict) or not required <= set(entry) or set(entry) - required - {"plural"}:
        raise ValueError(message_id + ": invalid message fields")
    source_text(entry["context"], message_id + ": context", nonempty=True)
    parameters, forms = entry["parameters"], entry["forms"]
    if not isinstance(parameters, dict) or any(
        not NAME.fullmatch(name) or kind not in KINDS
        for name, kind in parameters.items()
    ):
        raise ValueError(message_id + ": invalid parameter declaration")
    plural = entry.get("plural")
    if "plural" in entry:
        if not isinstance(plural, str) or parameters.get(plural) != "number":
            raise ValueError(message_id + ": plural must name a numeric parameter")
        expected_forms = {"one", "other"}
    else:
        expected_forms = {"other"}
    if not isinstance(forms, dict) or set(forms) != expected_forms:
        raise ValueError(message_id + ": invalid English forms")
    for form, pattern in forms.items():
        source_text(pattern, message_id + ": " + form)
        if placeholders(pattern) != set(parameters):
            raise ValueError(message_id + ": placeholder set does not match parameters")

def read_messages(native_root):
    locales = native_root / "locales"
    paths = [locales / "en.json", *sorted((locales / "en").glob("*.json"))]
    merged = {}
    for path in paths:
        data = json.loads(path.read_text(encoding="utf-8"),
                          object_pairs_hook=unique_object)
        if (not isinstance(data, dict) or set(data) != {"schema", "locale", "messages"}
                or data["schema"] != "cix-messages-v1" or data["locale"] != "en"
                or not isinstance(data["messages"], dict)):
            raise ValueError(str(path) + ": invalid English source catalog")
        for message_id, entry in data["messages"].items():
            if message_id in merged:
                raise ValueError("duplicate message ID across sources: " + message_id)
            validate_message(message_id, entry)
            merged[message_id] = entry
    return merged

def rust_string(value):
    # Preserve existing r#"..."# spelling; add hashes only for a delimiter collision.
    # Raw Rust strings cannot preserve lone CR. Encode controls using Rust escapes.
    def cooked():
        pieces = []
        for c in value:
            if c == "\\":
                pieces.append("\\\\")
            elif c == '"':
                pieces.append('\\"')
            elif ord(c) < 32:
                pieces.append("\\u{" + format(ord(c), "x") + "}")
            else:
                pieces.append(c)
        return '"' + "".join(pieces) + '"'
    if any(ord(c) < 32 and c not in "\n\t" for c in value):
        return cooked()
    hashes = "#"
    while '"' + hashes in value:
        if len(hashes) == 255:
            return cooked()
        hashes += "#"
    return "r" + hashes + '"' + value + '"' + hashes

def render(messages):
    lines = [HEADER]
    for message_id in sorted(messages):
        entry = messages[message_id]
        lines.extend([
            "    Definition {\n",
            "        id: " + rust_string(message_id) + ",\n",
            "        context: " + rust_string(entry["context"]) + ",\n",
            "        parameters: &[\n",
        ])
        for name, kind in sorted(entry["parameters"].items()):
            lines.append("            Parameter { name: " + rust_string(name)
                         + ", kind: ParameterKind::" + KINDS[kind] + " },\n")
        lines.extend([
            "        ],\n",
            "        other: " + rust_string(entry["forms"]["other"]) + ",\n",
            "        one: " + ("Some(" + rust_string(entry["forms"]["one"]) + ")"
                              if "one" in entry["forms"] else "None") + ",\n",
            "        plural: " + ("Some(" + rust_string(entry["plural"]) + ")"
                                 if "plural" in entry else "None") + ",\n",
            "    },\n",
        ])
    lines.append("];\n")
    return "".join(lines).encode("utf-8")

def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true",
                        help="validate schema and compare generated bytes without writing")
    args = parser.parse_args(argv)
    native_root = Path(__file__).resolve().parents[2] / "rust" / "cix-native"
    output = native_root / "src" / "i18n_catalog.rs"
    try:
        expected = render(read_messages(native_root))
        if args.check:
            if not output.is_file() or output.read_bytes() != expected:
                print("generated catalog is missing or differs from English sources", file=sys.stderr)
                return 1
        else:
            output.write_bytes(expected)
    except (OSError, ValueError, TypeError) as error:
        print("catalog validation failed: " + str(error), file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
